tion{position:absolute;right:18px;top:50%;writing-mode:vertical-rl;transform:translateY(-50%);font-size:8px;letter-spacing:3px;color:#ffffff52}.scene-decoration span{color:#e6c982}.narrative-panel{padding:16px 21px 15px;flex:1;min-height:230px}.narrative-top{display:flex;align-items:center;justify-content:space-between}.speaker{display:flex;align-items:center;gap:10px}.speaker-icon{display:grid;place-items:center;width:31px;height:31px;border:1px solid #d5bd843a;border-radius:50%;color:var(--gold);font-size:16px;background:#282536}.speaker b,.speaker small{display:block}.speaker b{font-size:10px;font-weight:600}.speaker small{font-size:7px;letter-spacing:1.5px;color:#9096a8;margin-top:3px}.memory-counter{font-size:8px;letter-spacing:1px;color:#9298a9}.memory-counter span{color:#b6a3e4;font-size:13px;margin-right:5px}.memory-counter b{color:#e4d6b8;margin-left:4px}.dialogue{font-family:var(--serif);font-size:13px;line-height:1.7;color:#d5d4db;margin:13px 0 13px}.choice-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.choice-button{display:flex;align-items:center;gap:10px;text-align:left;background:#202432;border:1px solid #ffffff0d;color:#d8d9e0;border-radius:6px;padding:10px 11px;min-height:42px;cursor:pointer;transition:all .2s}.choice-button:hover{background:#292a3a;border-color:#c3a76888;transform:translateY(-1px)}.choice-button:focus-visible{outline:2px solid var(--gold);outline-offset:2px}.choice-key{display:grid;place-items:center;flex:0 0 20px;width:20px;height:20px;border-radius:50%;background:#343144;color:#cfba87;font-size:9px}.choice-text{font-size:9px;line-height:1.4}.choice-arrow{margin-left:auto;color:#8f8b9b;font-size:14px}.memory-note{display:flex;align-items:start;gap:8px;border-top:1px solid var(--line);margin-top:12px;padding-top:10px;color:#d9c17e}.memory-note p{font-size:9px;color:#c3c0cf;margin:0;line-height:1.5}.status-row{display:flex;align-items:center;gap:10px}.status-chip{display:flex;align-items:center;gap:8px;padd