$('sound-toggle').addEventListener('click', event => {
  event.currentTarget.classList.toggle('sound-off');
  showToast(event.currentTarget.classList.contains('sound-off') ? '♪ Som ambiente desativado' : '♫ Som ambiente ativado');
});
